static LineNum lastLineNum(UPSAgreementId _agreementId)
{
    return (select maxof(LineNum) from UPSPriceTermJournalTrans
        index hint TransIdx
        where UPSPriceTermJournalTrans.AgreementId == _agreementId).LineNum;
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case (fieldNum(UPSPriceTermJournalTrans, Code)):
            this.initFromPriceTermCode(this.Code);
            break;
    }
}

private void initFromPriceTermCode(UPSPriceTermCode _priceTermCode)
{
    UPSPriceTermTable priceTerm = UPSPriceTermTable::findPriceTermCode(_priceTermCode);

    if (priceTerm)
    {
        this.CalculateMethod = priceTerm.CalculateMethod;
        this.Value = priceTerm.Value;
        this.ItemChargeCode = priceTerm.ItemChargeCode;
        this.CalculateBasePriceInventory = priceTerm.CalculateBasePriceInventory;
        this.CalculateBasePricePurchase = priceTerm.CalculateBasePricePurchase;
        this.CalculateBasePriceSales = priceTerm.CalculateBasePriceSales;
    }
}

/// <summary>
/// Initiates the current table buffer by using the specified table buffer.
/// </summary>
/// <param name="_upsPriceTermJournalTable">
/// A <c>UPSPriceTermJournalTable</c> table buffer.
/// </param>
public void initfromUPSPriceTermJournalTable(UPSPriceTermJournalTable _upsPriceTermJournalTable)
{
    this.AgreementId = _upsPriceTermJournalTable.AgreementId;

    if (_upsPriceTermJournalTable.ValidFrom)
    {
        this.ValidFrom = _upsPriceTermJournalTable.ValidFrom;
    }
    if (_upsPriceTermJournalTable.ValidTo)
    {
        this.ValidTo = _upsPriceTermJournalTable.ValidTo;
    }

    this.TransDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
}

/// <summary>
/// Initiates the current table buffer by using the specified table buffer.
/// </summary>
/// <param name="_upsPriceTermJournalTrans">
/// A <c>UPSPriceTermJournalTrans</c> table buffer.
/// </param>
public void initfromUPSPriceTermJournalTrans(UPSPriceTermJournalTrans _upsPriceTermJournalTrans)
{
    this.AgreementId                    = _upsPriceTermJournalTrans.AgreementId;
    this.CalculateBasePriceInventory    = _upsPriceTermJournalTrans.CalculateBasePriceInventory;
    this.CalculateBasePricePurchase     = _upsPriceTermJournalTrans.CalculateBasePricePurchase;
    this.CalculateBasePriceSales        = _upsPriceTermJournalTrans.CalculateBasePriceSales;
    this.CalculateMethod                = _upsPriceTermJournalTrans.CalculateMethod;
    this.CompoundCalculationBasis       = _upsPriceTermJournalTrans.CompoundCalculationBasis;
    this.CalculationSequence            = _upsPriceTermJournalTrans.CalculationSequence;
    this.Code                           = _upsPriceTermJournalTrans.Code;
    this.Value                          = _upsPriceTermJournalTrans.Value;
    this.ItemChargeCode                 = _upsPriceTermJournalTrans.ItemChargeCode;
    this.LineNum                        = UPSPriceTermJournalTrans::lastLineNum(_upsPriceTermJournalTrans.AgreementId) + 1;
    this.UnitId                         = _upsPriceTermJournalTrans.UnitId;
    this.ValidFrom                      = _upsPriceTermJournalTrans.ValidFrom;
    this.ValidTo                        = _upsPriceTermJournalTrans.ValidTo;
}

public static void lookupCode(UPSAgreementId     _agreementId,
                              FormStringControl _control)
{
    Query query = new Query();
    QueryBuildDataSource queryBuildDataSource;
    QueryBuildRange qbrAccountRelation;
    QueryBuildRange qbrAccountCode;
    SysTableLookup sysTableLookup;

    UPSPriceTermJournalTable upsPriceTermJournalTable = UPSPriceTermJournalTable::find(_agreementId);

    PriceDiscAccountRelation accountRelation = upsPriceTermJournalTable.AccountRelation;
    PriceDiscAccountCode     accountCode     = upsPriceTermJournalTable.AccountCode;

    sysTableLookup = SysTableLookup::newParameters(tableNum(UPSPriceTermTable),_control,true);
    sysTableLookup.parmUseLookupValue(false);
    sysTableLookup.addLookupfield(fieldNum(UPSPriceTermTable, Code));
    sysTableLookup.addLookupfield(fieldNum(UPSPriceTermTable, Description));
    queryBuildDataSource = query.addDataSource(tableNum(UPSPriceTermTable));
    queryBuildDataSource.addSortField(fieldnum(UPSPriceTermTable,Code ));
    qbrAccountRelation = queryBuildDataSource.addRange(fieldNum(UPSPriceTermTable, AccountRelation));
    qbrAccountRelation.value(accountRelation);
    qbrAccountCode = queryBuildDataSource.addRange(fieldNum(UPSPriceTermTable, AccountCode));
    qbrAccountCode.value(queryValue(accountCode));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

static UPSPriceTermJournalTrans find(UPSAgreementId     _agreementId,
                                     LineNum            _lineNum = 0,
                                     boolean            _update  = false)
{
    UPSPriceTermJournalTrans upsPriceTermJournalTrans;

    if (_agreementId)
    {
        if (_update)
        {
            upsPriceTermJournalTrans.selectForUpdate(_update);
        }
        if (_lineNum)
        {
            select firstonly upsPriceTermJournalTrans
                index hint TransIdx
                where upsPriceTermJournalTrans.AgreementId  == _agreementId
                &&    upsPriceTermJournalTrans.LineNum      == _lineNum;
        }
        else
        {
            select firstonly upsPriceTermJournalTrans
                index hint TransIdx
                where upsPriceTermJournalTrans.AgreementId == _agreementId;
        }
    }

    return upsPriceTermJournalTrans;
}

    static boolean exist(UPSAgreementId     _agreementId,
                          LineNum           _lineNum = naReal())
    {
        if (!_agreementId)
        {
            return false;
        }

        if (_lineNum == naReal())
        {
            return (select firstonly RecId from upsPriceTermJournalTrans
                        index hint TransIdx
                        where upsPriceTermJournalTrans.AgreementId == _agreementId).RecId != 0;
        }

        return (select firstonly RecId from upsPriceTermJournalTrans
                    index hint TransIdx
                    where upsPriceTermJournalTrans.AgreementId == _agreementId
                    &&    upsPriceTermJournalTrans.LineNum     == _lineNum).RecId != 0;
	}

public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if (ret)
    {
        if (!this.ValidFrom || !this.ValidTo)
        {
            return checkFailed(strFmt("@UnifiedPricingService:UPSPriceTermJournalTrans_Validate_NoValidDate", this.LineNum));
        }

        if (this.ValidFrom > this.ValidTo)
        {
            return checkFailed(strFmt("@UnifiedPricingService:UPSPriceTermJournalTrans_Validate_ToDateGtFromDate", this.LineNum));
        }

        if (this.ValidTo < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
        {
            return checkFailed(strFmt("@UnifiedPricingService:UPSPriceTermJournalTrans_Validate_ToDateLtToday", this.LineNum));
        }
    }

    return ret;
}

public void write()
{
    if (this.PricingRule && !this.upsPricingRule().PriceAttributeGroup)
    {
        UPSPricingRule::find(this.PricingRule, true).delete();
        this.PricingRule = 0;
    }

    super();
}
